# test_group_by.py
import pytest

from your_module import group_by  # replace "your_module" with the actual module name


def test_group_by_happy_path():
    items = ["apple", "apricot", "banana", "blueberry", "cherry"]

    result = group_by(items, key_fn=lambda x: x[0])

    assert result == {
        "a": ["apple", "apricot"],
        "b": ["banana", "blueberry"],
        "c": ["cherry"],
    }


def test_group_by_preserves_item_order_within_groups():
    items = [1, 3, 2, 5, 4, 6]

    result = group_by(items, key_fn=lambda x: x % 2)

    assert result == {
        1: [1, 3, 5],
        0: [2, 4, 6],
    }


def test_group_by_empty_list_returns_empty_dict():
    assert group_by([], key_fn=lambda x: x) == {}


def test_group_by_all_items_same_group():
    items = ["a", "b", "c"]

    result = group_by(items, key_fn=lambda _: "same")

    assert result == {
        "same": ["a", "b", "c"],
    }


def test_group_by_each_item_own_group():
    items = [1, 2, 3]

    result = group_by(items, key_fn=lambda x: x)

    assert result == {
        1: [1],
        2: [2],
        3: [3],
    }


def test_group_by_with_none_as_key():
    items = ["a", "b"]

    result = group_by(items, key_fn=lambda _: None)

    assert result == {
        None: ["a", "b"],
    }


def test_group_by_with_tuple_keys():
    items = [
        {"name": "Alice", "role": "admin", "active": True},
        {"name": "Bob", "role": "admin", "active": False},
        {"name": "Carol", "role": "user", "active": True},
    ]

    result = group_by(items, key_fn=lambda x: (x["role"], x["active"]))

    assert result == {
        ("admin", True): [{"name": "Alice", "role": "admin", "active": True}],
        ("admin", False): [{"name": "Bob", "role": "admin", "active": False}],
        ("user", True): [{"name": "Carol", "role": "user", "active": True}],
    }


def test_group_by_key_function_called_once_per_item():
    items = [1, 2, 3]
    calls = []

    def key_fn(item):
        calls.append(item)
        return item % 2

    group_by(items, key_fn)

    assert calls == [1, 2, 3]


def test_group_by_raises_when_key_function_raises():
    items = [1, 2, 0, 3]

    def key_fn(item):
        if item == 0:
            raise ValueError("zero is not allowed")
        return 10 / item

    with pytest.raises(ValueError, match="zero is not allowed"):
        group_by(items, key_fn)


def test_group_by_raises_when_key_is_unhashable():
    items = [1, 2, 3]

    with pytest.raises(TypeError):
        group_by(items, key_fn=lambda x: [x])


def test_group_by_raises_when_key_fn_is_not_callable():
    items = [1, 2, 3]

    with pytest.raises(TypeError):
        group_by(items, key_fn=None)


def test_group_by_raises_when_items_is_none():
    with pytest.raises(TypeError):
        group_by(None, key_fn=lambda x: x)
